import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]): string {
  return twMerge(clsx(inputs));
}

"use client";

import * as React from "react";
import { motion } from "framer-motion";
import { IconRefresh } from "@tabler/icons-react";
import { cn } from "@/lib/utils";

export interface StreamRevealTypographyProps {
  /** The full text to stream in */
  text: string;
  /** ms between each token reveal (default 22) */
  speed?: number;
  /** Token granularity */
  by?: "char" | "word";
  /** Replay key — change to restart the animation */
  replayKey?: string | number;
  /** Show a built-in "Replay" button below the text */
  showReplayButton?: boolean;
  /** Optional className for the container */
  className?: string;
  /** Called once the entire text has finished revealing */
  onComplete?: () => void;
}

/**
 * StreamRevealTypography
 *
 * Mimics LLM token streaming with a smooth opacity + translateY fade-in
 * for each token. No layout shift (text is always full-size, just hidden
 * via opacity), so animation runs entirely on transform + opacity = GPU.
 *
 * Renders ALL tokens immediately in the DOM but with opacity:0; reveals
 * them on a setInterval cursor. This avoids the typical "snap-to-text"
 * caused by appending characters which trigger reflow.
 */
export function StreamRevealTypography({
  text,
  speed = 22,
  by = "word",
  replayKey,
  showReplayButton = false,
  className,
  onComplete,
}: StreamRevealTypographyProps) {
  const tokens = React.useMemo(
    () => (by === "word" ? text.split(/(\s+)/) : Array.from(text)),
    [text, by]
  );
  const [revealed, setRevealed] = React.useState(0);
  const [internalKey, setInternalKey] = React.useState(0);

  React.useEffect(() => {
    setRevealed(0);
    let i = 0;
    const id = window.setInterval(() => {
      i++;
      setRevealed(i);
      if (i >= tokens.length) {
        window.clearInterval(id);
        onComplete?.();
      }
    }, speed);
    return () => window.clearInterval(id);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [tokens, speed, replayKey, internalKey]);

  const done = revealed >= tokens.length;

  return (
    <div className={cn("inline-block", className)}>
      <span className="inline-block leading-relaxed" aria-label={text}>
        {tokens.map((tok, i) => {
          const visible = i < revealed;
          if (/^\s+$/.test(tok)) {
            return <React.Fragment key={i}>{tok}</React.Fragment>;
          }
          return (
            <motion.span
              key={i}
              aria-hidden={!visible}
              initial={false}
              animate={{
                opacity: visible ? 1 : 0,
                y: visible ? 0 : 4,
              }}
              transition={{
                duration: 0.32,
                ease: [0.22, 1, 0.36, 1],
              }}
              className="inline-block"
              style={{ willChange: "transform, opacity" }}
            >
              {tok}
            </motion.span>
          );
        })}
        {!done && (
          <motion.span
            aria-hidden
            className="ml-0.5 inline-block h-[1em] w-[2px] -translate-y-[2px] rounded-sm bg-chili-500 align-middle"
            animate={{ opacity: [1, 0.2, 1] }}
            transition={{ duration: 1.05, repeat: Infinity, ease: "easeInOut" }}
            style={{ willChange: "opacity" }}
          />
        )}
      </span>

      {showReplayButton && (
        <div className="mt-5 flex">
          <button
            type="button"
            onClick={() => setInternalKey((v) => v + 1)}
            aria-label="Replay animation"
            className="group/replay inline-flex items-center gap-1.5 rounded-full border border-[var(--border)] bg-[var(--surface)] px-3 py-1.5 text-[12px] font-medium text-muted-foreground transition-colors hover:border-[var(--border-strong)] hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-chili-500"
          >
            <motion.span
              animate={{ rotate: done ? 0 : 360 }}
              transition={{
                duration: 1.4,
                repeat: done ? 0 : Infinity,
                ease: "linear",
              }}
              className="inline-flex"
              style={{ willChange: "transform" }}
            >
              <IconRefresh size={12} className="text-chili-500" />
            </motion.span>
            {done ? "Replay" : "Streaming…"}
          </button>
        </div>
      )}
    </div>
  );
}
